ALTER TABLE public.client_contacts ADD COLUMN all_sites boolean NOT NULL DEFAULT false, ADD COLUMN site_ids uuid[] NOT NULL DEFAULT '{}'::uuid[], ADD COLUMN delivery_preferences jsonb;
UPDATE public.client_contacts SET all_sites=(site_id IS NULL),site_ids=CASE WHEN site_id IS NULL THEN '{}'::uuid[] ELSE ARRAY[site_id] END;
CREATE TABLE public.client_portal_memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),client_id uuid NOT NULL REFERENCES public.clients(id),contact_id uuid NOT NULL REFERENCES public.client_contacts(id),user_id uuid NOT NULL,access_role text NOT NULL DEFAULT 'contact' CHECK(access_role IN('client_admin','contact')),all_sites boolean NOT NULL DEFAULT false,site_ids uuid[] NOT NULL DEFAULT '{}'::uuid[],revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,client_id));
GRANT SELECT ON public.client_portal_memberships TO authenticated; GRANT ALL ON public.client_portal_memberships TO service_role;
ALTER TABLE public.client_portal_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY portal_membership_own ON public.client_portal_memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR (company_id=public.current_company_id() AND public.is_company_manager()));
CREATE TABLE public.client_portal_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),client_id uuid NOT NULL REFERENCES public.clients(id),contact_id uuid NOT NULL REFERENCES public.client_contacts(id),email text NOT NULL,access_role text NOT NULL DEFAULT 'contact' CHECK(access_role IN('client_admin','contact')),all_sites boolean NOT NULL DEFAULT false,site_ids uuid[] NOT NULL DEFAULT '{}'::uuid[],token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL DEFAULT now()+interval '14 days',used_at timestamptz,revoked_at timestamptz,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.client_portal_invites TO authenticated; GRANT ALL ON public.client_portal_invites TO service_role;
ALTER TABLE public.client_portal_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY portal_invites_manager ON public.client_portal_invites FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.is_company_manager());
CREATE TABLE public.client_portal_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,client_id uuid NOT NULL,actor_id uuid NOT NULL,action text NOT NULL,contact_id uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.client_portal_audit TO authenticated; GRANT ALL ON public.client_portal_audit TO service_role;
ALTER TABLE public.client_portal_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY portal_audit_office ON public.client_portal_audit FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.has_company_role('admin'));
CREATE OR REPLACE FUNCTION public.client_workspace_scope(_client uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.clients; m public.client_portal_memberships; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to continue'; END IF;
 SELECT * INTO c FROM public.clients WHERE id=_client;
 IF NOT FOUND THEN RAISE EXCEPTION 'Client unavailable'; END IF;
 IF c.company_id=public.current_company_id() AND public.is_company_manager() THEN RETURN jsonb_build_object('office',true,'admin',true,'company',c.company_id,'all_sites',true,'site_ids','[]'::jsonb); END IF;
 SELECT * INTO m FROM public.client_portal_memberships WHERE user_id=auth.uid() AND client_id=_client AND company_id=c.company_id AND revoked_at IS NULL;
 IF NOT FOUND OR NOT public.company_module_access(c.company_id,'client_portal') THEN RAISE EXCEPTION 'Client portal access unavailable'; END IF;
 RETURN jsonb_build_object('office',false,'admin',m.access_role='client_admin','company',m.company_id,'all_sites',m.all_sites,'site_ids',to_jsonb(m.site_ids),'contact',m.contact_id);
END $$;
REVOKE ALL ON FUNCTION public.client_workspace_scope(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.client_workspace_scope(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.client_portal_directory() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'company',co.name,'enabled',public.company_module_access(c.company_id,'client_portal'))),'[]'::jsonb) FROM public.client_portal_memberships m JOIN public.clients c ON c.id=m.client_id AND c.company_id=m.company_id JOIN public.companies co ON co.id=m.company_id WHERE m.user_id=auth.uid() AND m.revoked_at IS NULL $$;
REVOKE ALL ON FUNCTION public.client_portal_directory() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.client_portal_directory() TO authenticated;
CREATE OR REPLACE FUNCTION public.client_workspace(_client uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE scope jsonb:=public.client_workspace_scope(_client); c public.clients; contacts jsonb; sites jsonb; sheets jsonb; BEGIN
 SELECT * INTO c FROM public.clients WHERE id=_client;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'address',s.address) ORDER BY s.name),'[]'::jsonb) INTO sites FROM public.sites s WHERE s.client_id=c.id AND s.company_id=c.company_id AND ((scope->>'all_sites')::boolean OR to_jsonb(s.id::text)<@coalesce(scope->'site_ids','[]'::jsonb));
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'first_name',x.first_name,'last_name',x.last_name,'email',x.email,'phone',x.phone,'role_title',x.role_title,'has_whatsapp',x.has_whatsapp,'receives_job_sheets',x.receives_job_sheets,'site_id',x.site_id,'site_ids',x.site_ids,'all_sites',x.all_sites,'delivery_preferences',x.delivery_preferences) ORDER BY x.first_name),'[]'::jsonb) INTO contacts FROM public.client_contacts x WHERE x.client_id=c.id AND x.company_id=c.company_id AND ((scope->>'office')::boolean OR (x.id::text=scope->>'contact') OR ((scope->>'admin')::boolean AND ((scope->>'all_sites')::boolean OR (NOT x.all_sites AND to_jsonb(x.site_ids)<@scope->'site_ids'))));
 SELECT coalesce(jsonb_agg(q),'[]'::jsonb) INTO sheets FROM (SELECT s.id,s.jobsheet_number,s.created_at,s.site_id,s.reported_fault,s.repairs_performed FROM public.job_sheets s WHERE s.client_id=c.id AND s.company_id=c.company_id AND s.status='completed' AND ((scope->>'office')::boolean OR (scope->>'all_sites')::boolean OR (s.site_id IS NOT NULL AND to_jsonb(s.site_id::text)<@scope->'site_ids')) ORDER BY s.created_at DESC LIMIT 100) q;
 RETURN jsonb_build_object('id',c.id,'name',c.name,'company_id',c.company_id,'scope',scope,'sites',sites,'contacts',contacts,'sheets',sheets,'module_on',public.company_module_access(c.company_id,'client_portal'));
END $$;
REVOKE ALL ON FUNCTION public.client_workspace(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.client_workspace(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.save_client_contact(_client uuid,_contact uuid,_details jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE scope jsonb:=public.client_workspace_scope(_client); c public.client_contacts; cid uuid; allsites boolean:=coalesce((_details->>'all_sites')::boolean,false); ids uuid[]; pref jsonb:=_details->'delivery_preferences'; k text; v jsonb; BEGIN
 IF NOT public.company_module_access((scope->>'company')::uuid,'client_portal') THEN RAISE EXCEPTION 'Client Experience module required'; END IF;
 SELECT coalesce(array_agg(value::uuid),'{}'::uuid[]) INTO ids FROM jsonb_array_elements_text(coalesce(_details->'site_ids','[]'::jsonb));
 IF cardinality(ids)<> (SELECT count(DISTINCT x) FROM unnest(ids)x) OR EXISTS(SELECT 1 FROM unnest(ids)x WHERE NOT EXISTS(SELECT 1 FROM public.sites WHERE id=x AND client_id=_client AND company_id=(scope->>'company')::uuid)) THEN RAISE EXCEPTION 'Choose sites belonging to this client'; END IF;
 IF NOT (scope->>'office')::boolean AND NOT (scope->>'all_sites')::boolean AND (allsites OR NOT to_jsonb(ids)<@scope->'site_ids') THEN RAISE EXCEPTION 'Cannot expand site access'; END IF;
 IF _contact IS NOT NULL THEN SELECT * INTO c FROM public.client_contacts WHERE id=_contact AND client_id=_client AND company_id=(scope->>'company')::uuid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Contact unavailable'; END IF; END IF;
 IF NOT (scope->>'admin')::boolean THEN
 IF _contact IS NULL OR _contact::text IS DISTINCT FROM scope->>'contact' OR allsites IS DISTINCT FROM c.all_sites OR ids IS DISTINCT FROM c.site_ids THEN RAISE EXCEPTION 'You can edit only your own contact details without changing site access'; END IF;
 ELSIF NOT (scope->>'office')::boolean AND NOT (scope->>'all_sites')::boolean AND _contact IS NOT NULL AND (c.all_sites OR NOT to_jsonb(c.site_ids)<@scope->'site_ids') THEN RAISE EXCEPTION 'Contact outside your site authority'; END IF;
 IF length(trim(coalesce(_details->>'first_name','')))=0 OR length(_details->>'first_name')>100 OR length(coalesce(_details->>'last_name',''))>100 OR length(coalesce(_details->>'phone',''))>40 OR length(coalesce(_details->>'role_title',''))>100 OR (_details->>'email') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(_details->>'email')>254 THEN RAISE EXCEPTION 'Enter valid contact details'; END IF;
 IF pref IS NOT NULL AND pref<>'null'::jsonb THEN
 IF jsonb_typeof(pref)<>'object' THEN RAISE EXCEPTION 'Invalid delivery preferences'; END IF;
 FOR k,v IN SELECT * FROM jsonb_each(pref) LOOP
 IF k NOT IN('job_sheet','eta','estimate','proposal','contract','invoice','no_access','unsigned_left') OR jsonb_typeof(v)<>'object' OR jsonb_typeof(v->'email')<>'boolean' OR jsonb_typeof(v->'whatsapp')<>'boolean' THEN RAISE EXCEPTION 'Invalid document or channel preference'; END IF;
 IF coalesce((v->>'whatsapp')::boolean,false) AND NOT coalesce((_details->>'has_whatsapp')::boolean,false) THEN RAISE EXCEPTION 'WhatsApp requires contact consent'; END IF;
 END LOOP; END IF;
 IF _contact IS NULL THEN INSERT INTO public.client_contacts(company_id,client_id,first_name,last_name,email,phone,role_title,all_sites,site_ids,site_id,delivery_preferences,has_whatsapp,receives_job_sheets) VALUES((scope->>'company')::uuid,_client,trim(_details->>'first_name'),trim(_details->>'last_name'),lower(trim(_details->>'email')),trim(_details->>'phone'),trim(_details->>'role_title'),allsites,ids,CASE WHEN allsites THEN NULL ELSE ids[1] END,pref,coalesce((_details->>'has_whatsapp')::boolean,false),coalesce((pref->'job_sheet'->>'email')::boolean,false)) RETURNING id INTO cid;
 ELSE UPDATE public.client_contacts SET first_name=trim(_details->>'first_name'),last_name=trim(_details->>'last_name'),email=lower(trim(_details->>'email')),phone=trim(_details->>'phone'),role_title=trim(_details->>'role_title'),all_sites=allsites,site_ids=ids,site_id=CASE WHEN allsites THEN NULL ELSE ids[1] END,delivery_preferences=pref,has_whatsapp=coalesce((_details->>'has_whatsapp')::boolean,false),receives_job_sheets=coalesce((pref->'job_sheet'->>'email')::boolean,false) WHERE id=_contact RETURNING id INTO cid; END IF;
 INSERT INTO public.client_portal_audit(company_id,client_id,actor_id,action,contact_id) VALUES((scope->>'company')::uuid,_client,auth.uid(),'contact_saved',cid); RETURN cid;
END $$;
REVOKE ALL ON FUNCTION public.save_client_contact(uuid,uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_client_contact(uuid,uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.invite_client_contact(_client uuid,_contact uuid,_admin boolean DEFAULT false) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE scope jsonb:=public.client_workspace_scope(_client); c public.client_contacts; token text:=encode(extensions.gen_random_bytes(32),'hex'); BEGIN
 IF NOT (scope->>'admin')::boolean OR NOT public.company_module_access((scope->>'company')::uuid,'client_portal') OR (_admin AND NOT (scope->>'office')::boolean) THEN RAISE EXCEPTION 'Only authorised administrators can invite clients'; END IF;
 SELECT * INTO c FROM public.client_contacts WHERE id=_contact AND client_id=_client AND company_id=(scope->>'company')::uuid;
 IF NOT FOUND OR c.email IS NULL OR c.email='' THEN RAISE EXCEPTION 'Contact with email required'; END IF;
 IF NOT (scope->>'all_sites')::boolean AND (c.all_sites OR NOT to_jsonb(c.site_ids)<@scope->'site_ids') THEN RAISE EXCEPTION 'Contact outside your site authority'; END IF;
 INSERT INTO public.client_portal_invites(company_id,client_id,contact_id,email,access_role,all_sites,site_ids,token_hash,created_by) VALUES(c.company_id,c.client_id,c.id,lower(trim(c.email)),CASE WHEN _admin THEN 'client_admin' ELSE 'contact' END,c.all_sites,c.site_ids,encode(extensions.digest(token,'sha256'),'hex'),auth.uid());
 INSERT INTO public.client_portal_audit(company_id,client_id,actor_id,action,contact_id) VALUES(c.company_id,c.client_id,auth.uid(),'invitation_created',c.id); RETURN token;
END $$;
REVOKE ALL ON FUNCTION public.invite_client_contact(uuid,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.invite_client_contact(uuid,uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.accept_client_portal_invite(_token text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.client_portal_invites; account_email text; confirmed timestamptz; BEGIN
 IF auth.uid() IS NULL OR _token !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Sign in with your invited account'; END IF;
 SELECT email,email_confirmed_at INTO account_email,confirmed FROM auth.users WHERE id=auth.uid();
 IF confirmed IS NULL THEN RAISE EXCEPTION 'Confirm your email before joining'; END IF;
 IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Use a client account, not an employee account'; END IF;
 SELECT * INTO i FROM public.client_portal_invites WHERE token_hash=encode(extensions.digest(_token,'sha256'),'hex') AND used_at IS NULL AND revoked_at IS NULL AND expires_at>now() FOR UPDATE;
 IF NOT FOUND OR lower(trim(account_email)) IS DISTINCT FROM i.email OR NOT public.company_module_access(i.company_id,'client_portal') THEN RAISE EXCEPTION 'Invitation unavailable or account email does not match'; END IF;
 INSERT INTO public.client_portal_memberships(company_id,client_id,contact_id,user_id,access_role,all_sites,site_ids) VALUES(i.company_id,i.client_id,i.contact_id,auth.uid(),i.access_role,i.all_sites,i.site_ids) ON CONFLICT(user_id,client_id) DO UPDATE SET contact_id=EXCLUDED.contact_id,access_role=EXCLUDED.access_role,all_sites=EXCLUDED.all_sites,site_ids=EXCLUDED.site_ids,revoked_at=NULL;
 UPDATE public.client_portal_invites SET used_at=now() WHERE id=i.id;
 INSERT INTO public.client_portal_audit(company_id,client_id,actor_id,action,contact_id) VALUES(i.company_id,i.client_id,auth.uid(),'invitation_accepted',i.contact_id); RETURN i.client_id;
END $$;
REVOKE ALL ON FUNCTION public.accept_client_portal_invite(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.accept_client_portal_invite(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.revoke_client_portal_access(_client uuid,_contact uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE scope jsonb:=public.client_workspace_scope(_client); BEGIN IF NOT (scope->>'office')::boolean THEN RAISE EXCEPTION 'Contractor manager access required'; END IF; UPDATE public.client_portal_memberships SET revoked_at=now() WHERE client_id=_client AND contact_id=_contact AND company_id=(scope->>'company')::uuid; UPDATE public.client_portal_invites SET revoked_at=now() WHERE client_id=_client AND contact_id=_contact AND company_id=(scope->>'company')::uuid AND used_at IS NULL; INSERT INTO public.client_portal_audit(company_id,client_id,actor_id,action,contact_id) VALUES((scope->>'company')::uuid,_client,auth.uid(),'access_revoked',_contact); END $$;
REVOKE ALL ON FUNCTION public.revoke_client_portal_access(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.revoke_client_portal_access(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.client_message_recipients(_client uuid,_site uuid,_purpose text,_channel text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.clients; advanced boolean; BEGIN
 SELECT * INTO c FROM public.clients WHERE id=_client AND company_id=public.current_company_id(); IF NOT FOUND OR NOT public.member_is_active(auth.uid()) THEN RAISE EXCEPTION 'Company access required'; END IF;
 IF _site IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sites WHERE id=_site AND client_id=c.id AND company_id=c.company_id) THEN RAISE EXCEPTION 'Site does not belong to this client'; END IF;
 IF _purpose NOT IN('job_sheet','eta','estimate','proposal','contract','invoice','no_access','unsigned_left') OR _channel NOT IN('email','whatsapp') THEN RAISE EXCEPTION 'Invalid delivery purpose or channel'; END IF;
 advanced:=public.company_module_access(c.company_id,'client_portal');
 RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'first_name',x.first_name,'email',x.email,'phone',x.phone)),'[]'::jsonb) FROM public.client_contacts x WHERE x.client_id=c.id AND x.company_id=c.company_id AND (CASE WHEN advanced AND x.delivery_preferences IS NOT NULL THEN (x.all_sites OR (_site IS NOT NULL AND _site=ANY(x.site_ids))) AND coalesce((x.delivery_preferences->_purpose->>_channel)::boolean,false) ELSE (x.site_id IS NULL OR x.site_id=_site) AND CASE WHEN _channel='email' THEN x.receives_job_sheets OR (_purpose<>'job_sheet' AND x.is_primary_contact) ELSE x.has_whatsapp END END) AND CASE WHEN _channel='email' THEN nullif(trim(x.email),'') IS NOT NULL ELSE x.has_whatsapp AND nullif(trim(x.phone),'') IS NOT NULL END);
END $$;
REVOKE ALL ON FUNCTION public.client_message_recipients(uuid,uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.client_message_recipients(uuid,uuid,text,text) TO authenticated;